// House Music Bass Pattern Generator
const bpm = $input.first().json.bpm || 128;
const bars = $input.first().json.bars || 8;
const key = $input.first().json.key || 'A';
const scale = $input.first().json.scale || 'minor';
const ticksPerBeat = 480;
const beatsPerBar = 4;

// Note mapping
const noteToMidi = {
  'C': 0, 'C#': 1, 'Db': 1, 'D': 2, 'D#': 3, 'Eb': 3,
  'E': 4, 'F': 5, 'F#': 6, 'Gb': 6, 'G': 7, 'G#': 8,
  'Ab': 8, 'A': 9, 'A#': 10, 'Bb': 10, 'B': 11
};

// Scale intervals (semitones from root)
const scaleIntervals = {
  'minor': [0, 2, 3, 5, 7, 8, 10],      // Natural minor
  'major': [0, 2, 4, 5, 7, 9, 11],       // Major
  'dorian': [0, 2, 3, 5, 7, 9, 10],      // Dorian (common in house)
  'phrygian': [0, 1, 3, 5, 7, 8, 10]     // Phrygian
};

// Get root note MIDI number (octave 1 for bass)
const rootNote = noteToMidi[key] + 24; // C1 = 24
const intervals = scaleIntervals[scale] || scaleIntervals['minor'];

// Create scale notes for bass (2 octaves)
const scaleNotes = [];
for (let octave = 0; octave < 2; octave++) {
  intervals.forEach(interval => {
    scaleNotes.push(rootNote + interval + (octave * 12));
  });
}

const midiEvents = [];
let eventId = 0;

// House bass patterns (16th note patterns)
const bassPatterns = [
  // Pattern 1: Root heavy with octave jumps
  [
    { step: 0, note: 0, duration: 2, velocity: 100 },   // Root
    { step: 2, note: 0, duration: 1, velocity: 80 },    // Root
    { step: 4, note: 7, duration: 2, velocity: 90 },    // Fifth
    { step: 6, note: 0, duration: 1, velocity: 85 },    // Root
    { step: 8, note: 0, duration: 2, velocity: 100 },   // Root
    { step: 10, note: 3, duration: 1, velocity: 85 },   // Third
    { step: 12, note: 0, duration: 2, velocity: 95 },   // Root
    { step: 14, note: 7, duration: 1, velocity: 80 }    // Fifth
  ],
  // Pattern 2: Syncopated groove
  [
    { step: 0, note: 0, duration: 1.5, velocity: 100 },
    { step: 2, note: 7, duration: 1, velocity: 85 },
    { step: 3.5, note: 0, duration: 1, velocity: 90 },
    { step: 5, note: 3, duration: 1.5, velocity: 85 },
    { step: 7, note: 0, duration: 1, velocity: 95 },
    { step: 8, note: 0, duration: 2, velocity: 100 },
    { step: 11, note: 5, duration: 1, velocity: 80 },
    { step: 13, note: 0, duration: 1.5, velocity: 90 },
    { step: 15, note: 7, duration: 0.5, velocity: 75 }
  ]
];

// Generate bass line
for (let bar = 0; bar < bars; bar++) {
  const patternIndex = Math.floor(bar / 2) % bassPatterns.length;
  const pattern = bassPatterns[patternIndex];

  // Progression: I - VI - III - VII (common house progression)
  const progressionDegrees = [0, 5, 2, 6];
  const chordRoot = progressionDegrees[bar % 4];

  pattern.forEach(note => {
    const tick = (bar * beatsPerBar * ticksPerBeat) + (note.step * ticksPerBeat / 4);
    const noteIndex = (chordRoot + note.note) % scaleNotes.length;

    midiEvents.push({
      id: eventId++,
      type: 'noteOn',
      tick: tick,
      note: scaleNotes[noteIndex],
      velocity: note.velocity,
      channel: 0,
      duration: (note.duration * ticksPerBeat / 4)
    });
  });
}

// Sort by tick
midiEvents.sort((a, b) => a.tick - b.tick);

return {
  json: {
    instrument: 'bass',
    bpm: bpm,
    bars: bars,
    key: key,
    scale: scale,
    events: midiEvents,
    totalTicks: bars * beatsPerBar * ticksPerBeat,
    ticksPerBeat: ticksPerBeat
  }
};

// Convert to MIDI file format
const data = $input.first().json;
const { events, bpm, ticksPerBeat, bars, key, scale } = data;

const midiData = {
  format: 0,
  tracks: 1,
  ticksPerBeat: ticksPerBeat,
  bpm: bpm,
  track: {
    name: `House Bass - ${key} ${scale}`,
    channel: 0,
    events: events.map(e => ({
      type: e.type,
      tick: e.tick,
      note: e.note,
      velocity: e.velocity,
      duration: e.duration
    }))
  }
};

return {
  json: {
    ...data,
    midiData: midiData,
    filename: `house_bass_${key}_${scale}_${bpm}bpm_${bars}bars.mid`
  }
};
